INSERT INTO "document_pages" ("document_id", "page", "text") VALUES (2, 1, 'Таблица И.1 - Учебный отгон. На учебной дороге длина отгона принимается равной от 5 до 10 м
при регулировании светофором, 14 м - с помощью знаков 2.6 и 2.7.');
INSERT INTO "document_pages" ("document_id", "page", "text") VALUES (2, 2, '6.4.2 Учебное регулирование вводится, если длина участка:
- менее 50 м при интенсивности движения от 250 до 520 авт/ч.
6.4.4 Учебный разъезд со знаками 2.6 и 2.7 допускается на участках
протяженностью менее 45 м с интенсивностью движения менее 260
авт/ч в двух направлениях.');
INSERT INTO "document_pages" ("document_id", "page", "text") VALUES (2, 3, 'Т а б л и ц а 5 - Учебное расстояние от регулировщика
Скорость, км/ч Расстояние, м
30 12
50 34
13.7.5 Следующий пункт.');
